def test_equal(x, y):   
    if isinstance(x, float) and isinstance(y, float):
        if math.isnan(x):
            return math.isnan(y)
        return math.isclose(x, y, rel_tol=1e-06, abs_tol=1e-12)
    elif isinstance(x, list) and isinstance(y, list):
        if len(x) != len(y):
            return False
        return all(test_equal(a, b) for a, b in zip(x, y))
    elif isinstance(x, tuple) and isinstance(y, tuple):
        if len(x) != len(y):
            return False
        return all(test_equal(a, b) for a, b in zip(x, y))
    else:
        return x == y

