def show_failed_test(setup, function, args):
    print('\u274C Test Failed:')
    print()     
    if setup:
        for input in setup.split(';'):
            print(input.replace(':', ' = '))
        print()
    print(f'{function.__name__}({args.rstrip(",")})')
    print()    
    




def run_tests(function, explain=True, relies_on = []):
    _globals = { }
    _locals = {}

    relies_on.append(function)

    for other_function in relies_on:
        _globals[other_function.__name__] = FunctionType(other_function.__code__, _globals, name=other_function.__name__, argdefs= other_function.__defaults__, closure= other_function.__closure__)  
    
    _globals['Direction'] = Direction
    _globals['math'] = math
    _globals['copy'] = copy
    _globals['_callbacks'] = _callbacks
    _globals['_callback'] = _callback    
    _globals['is_fan_cell2'] = is_fan_cell2
    _globals['is_fan_cell3'] = is_fan_cell3
    
    if explain:
        print()
    count = 0
    if function.__name__ in tests:
        for setup, args_str, expected_result in tests[function.__name__]:
            if setup:
                src = setup.replace(':', ' = ')
                exec(src, _globals, _locals)
            try:
                actual_result = eval(f'{function.__name__}({args_str})', _globals, _locals)
            except Exception as e:
                if explain:
                    show_failed_test(setup, function, args_str)
                    print('Crashed with runtime exception:')
                    traceback.print_exc()
                return False

            if ':' in expected_result:
                # Returns None, instead modifies its input parameters
                if actual_result != None:
                    if explain:
                        show_failed_test(setup, function, args_str)
                        print(f'Expected result: None')
                        print(f'Actual result: {actual_result}')
                        print('This function is meant to update the input parameter(s), not return a value')
                    return False
                    
                for part in expected_result.split(';'):      
                    name,expect = part.split(':')
                    actual = eval(name, _globals, _locals)
                    expected = eval(expect, _globals, _locals)
                    if not test_equal(actual, expected):
                        if explain:
                            show_failed_test(setup, function, args_str)
                            print(f'{name} is expected to be: {expected}')
                            print(f'But {name} is actually  : {actual}')
                        return False
            else:
                # Normal result, doesn't modify its input parameters
                if not test_equal(actual_result, eval(expected_result, _globals, _locals)):
                    if explain:
                        show_failed_test(setup, function, args_str)
                        print(f'Expected result: {expected_result}')
                        print(f'Actual result: {actual_result}')
                    return False
                
                if setup:
                    for input in setup.split(';'):
                        if not input.startswith('def '):    
                            parts = input.split(':')
                            expected = eval(parts[1], _globals, _locals)
                            actual = eval(parts[0], _globals, _locals)
                            if not test_equal(actual, expected):
                                if explain:
                                    show_failed_test(setup, function, args_str)
                                    print(f'Input parameter {parts[0]} should not be modified')
                                    print(f'It should remain as: {expected}')
                                    print(f'But has changed to : {actual}')
                                return False
            count += 1

    if explain:
        print(f'\u2705 Passed all ({count}) tests, well done!')            
    return True